<div class="row g-4"><div class="col-xl-5"><section class="customer-card"><h2>İzin talebi oluştur</h2><form method="post" action="<?= e(url('employee/leaves/request')) ?>" class="admin-form"><?= App\Core\Csrf::field() ?><label for="leave-start">Başlangıç tarihi / saati</label><input class="form-control" id="leave-start" name="start_at" type="datetime-local" required><label for="leave-end">Bitiş tarihi / saati</label><input class="form-control" id="leave-end" name="end_at" type="datetime-local" required><label for="leave-reason">Açıklama</label><textarea class="form-control" id="leave-reason" name="reason" minlength="3" maxlength="1000" rows="4" required></textarea><p class="muted">Talep takvimi kapatmaz. Yönetici onayında randevu çakışmaları kontrol edilir; onaylanan izin müsaitliği kapatır.</p><button class="btn btn-lumera" type="submit">İzin talebini gönder</button></form></section></div><div class="col-xl-7"><section class="customer-card"><h2>Talepleriniz</h2><?php if(!$requests): ?><p class="empty-state">Henüz izin talebiniz yok.</p><?php endif ?><?php foreach($requests as$q): ?><article class="leave-card"><div class="section-heading"><strong>#<?= (int)$q['id'] ?> · <?= e($requestLabels[$q['status']]) ?></strong></div><p><?= e(date('d.m.Y H:i',strtotime($q['start_at'])).' – '.date('d.m.Y H:i',strtotime($q['end_at']))) ?></p><p class="text-break"><?= e($q['reason']) ?></p><p><?= e($q['response']??'Değerlendirme bekleniyor.') ?></p><?php if($q['status']==='approved'&&!$q['approved_leave_id']): ?><p class="muted">Bu iznin takvim kaydı yönetici tarafından kaldırılmıştır; talep geçmişi korunur.</p><?php endif ?></article><?php endforeach ?></section><section class="customer-card mt-4"><h2>Takvime işlenen izinler</h2><?php if(!$leaves): ?><p>Onaylı izin bulunmuyor.</p><?php endif ?><?php foreach($leaves as$l): ?><p><?= e(date('d.m.Y H:i',strtotime($l['start_at'])).' – '.date('d.m.Y H:i',strtotime($l['end_at']))) ?><br><?= e($l['reason']??'') ?></p><?php endforeach ?></section></div></div>
